// SALAH reading preview. Surahs 112–114 use Islam.Global spelling with SALAH kaf/qaf notation.
// Source URLs remain in the data metadata; no new attribution is added to the reading cards.
// Editorial draft: not approved as a pronunciation guide.
const FATIHA=[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","Бисмилляахир-рахмаанир-рахиим"],[2,"ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَٰلَمِينَ","Аль-хамду лиллаахи раббиль-‘ааламиин"],[3,"ٱلرَّحْمَٰنِ ٱلرَّحِيمِ","Ар-рахмаанир-рахиим"],[4,"مَٰلِكِ يَوْمِ ٱلدِّينِ","Маалики йаумид-диин"],[5,"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","Иййаака на‘буду уа иййаака наста‘иин"],[6,"ٱهْدِنَا ٱلصِّرَٰطَ ٱلْمُسْتَقِيمَ","Ихдинас-сырааталь-мустақиим"],[7,"صِرَٰطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ","Сырааталь-лазиина ан‘амта ‘алейхим, гайриль-магдууби ‘алейхим уа лад-дааллиин"]];
const READINGS={1:FATIHA,112:[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ هُوَ ٱللَّهُ أَحَدٌ","Бисмилляахир-рахмаанир-рахиим. Қуль хуАллааху Ахад"],[2,"ٱللَّهُ ٱلصَّمَدُ","Аллаахус-Самад"],[3,"لَمْ يَلِدْ وَلَمْ يُولَدْ","Лям ялид уа лям юляд"],[4,"وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ","Уа лям якулляху куфууан Ахад"]],113:[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ","Бисмилляахир-рахмаанир-рахиим. Қуль А`узу Бираббиль-Фаляқ"],[2,"مِن شَرِّ مَا خَلَقَ","Мин Шарри Ма Халяқ"],[3,"وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ","Уа Мин Шарри Гасиқыйн Иза Уақаб"],[4,"وَمِن شَرِّ ٱلنَّفَّٰثَٰتِ فِى ٱلْعُقَدِ","Уа Мин Шаррин-Наффасати Филь-`Уқад"],[5,"وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ","Уа Мин Шарри Хасидин Иза Хасад"]],114:[[1,"بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ","Бисмилляахир-рахмаанир-рахиим. Қуль А`узу Бираббин-Наас"],[2,"مَلِكِ ٱلنَّاسِ","Маликин-Наас"],[3,"إِلَٰهِ ٱلنَّاسِ","Иляхин-Наас"],[4,"مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ","Мин Шарриль-Уасуасиль-Ханнаас"],[5,"ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ","Аль-Лязи Йувасвису Фи Судурин-Наас"],[6,"مِنَ ٱلْجِنَّةِ وَٱلنَّاسِ","Миналь-Джиннати Уан-Наас"]]};
const clean=t=>String(t).replace(/\ufeff/g,'');
// Accidental Arabic/source drift check; file authenticity remains SHA-256 verified in quran-data.
export function arabicReadingKey(text){let h=2166136261;for(const c of String(text)){h=Math.imul(h^c.charCodeAt(0),16777619)}return(h>>>0).toString(16).padStart(8,'0')}
function hasManualReading(surah){const rows=READINGS[surah?.number];return !!rows&&surah.verses?.length===rows.length&&surah.verses.every((v,i)=>v.ayah===rows[i][0]&&clean(v.arabic)===rows[i][1])}
function generatedReading(surah,verse){const data=surah?.salahReading;if(data?.edition!=='salah-reading-v2'||data.number!==surah.number||data.verses?.length!==surah.verses.length)return null;const row=data.verses[verse.ayah-1];return row?.ayah===verse.ayah&&row.arabicKey===arabicReadingKey(verse.arabic)&&typeof row.text==='string'&&row.text.trim()?row.text:null}
export function hasOwnTranscription(surah){return hasManualReading(surah)||!!surah?.verses?.length&&surah.verses.every(v=>generatedReading(surah,v)!==null)}
// SALAH spelling for the particle "ля", including attached уа/фа. Other words keep their notation.
// Formatting happens after integrity verification so already saved Quran files remain usable.
export function formatSalahTranscription(text){return text.replace(/(^|[^\p{L}\p{M}‘’])((?:[УуФф]а)?[Лл]я)а(?=$|[^\p{L}\p{M}])/gu,'$1$2')}
export function readingTranscription(surah,verse,edition){if(edition!=='salah-preview')return verse.transliteration;if(READINGS[surah?.number]&&hasManualReading(surah))return formatSalahTranscription(READINGS[surah.number][verse.ayah-1][2]);const generated=generatedReading(surah,verse);return generated?formatSalahTranscription(generated):verse.transliteration}
export const ownTranscriptionNote='Транскрипция SALAH: к — ك, қ — ق; аа, ии, уу обозначают долгий звук, а не точное число счётов. Знак ‘ передаёт ‘айн, ’ — хамзу. Окончания аятов даны для остановки. Транскрипция упрощённая и не передаёт всех правил таджвида. Полный вариант подготовлен по арабскому тексту с фонетическим движком Quran Transcript (Хафс); проверка всех аятов преподавателем ещё не выполнена. Для точного произношения слушайте чтеца.';
